      "text": "import (\n\t\"bytes\"\n\t\"errors\"\n\t\"flag\"\n\t\"fmt\"\n\t\"io\"\n\t\"os\"\n\n\t\"github.com/tdeshazo/repoctx/pkg/artifacts\"\n)"
