 71	func readBounded(path string, max int64) ([]byte, error) {
 72		file, err := os.Open(path)
 73		if err != nil {
 74			return nil, err
 75		}
 76		defer file.Close()
 77		content, err := io.ReadAll(io.LimitReader(file, max+1))
 78		if err != nil {
 79			return nil, err
 80		}
 81		if int64(len(content)) > max {
 82			return nil, fmt.Errorf("file exceeds byte limit")
 83		}
 84		return content, nil
 85	}
