153		}
154		if !utf8.Valid(data) {
155			return nil, limits, failure("$", "invalid UTF-8")
156		}
157		if err := checkEscapes(data); err != nil {
158			return nil, limits, err
159		}
160		decoder := json.NewDecoder(bytes.NewReader(data))
161		decoder.UseNumber()
162		if err := scan(decoder, 0, normalized.Depth); err != nil {
163			return nil, limits, err
164		}
165		if _, err := decoder.Token(); err != io.EOF {
166			return nil, limits, failure("$", "trailing JSON or invalid syntax")
167		}
